import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787777736000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="freshrss-rejects-the-login-401" tabindex="-1">FreshRSS rejects the login (401) <a class="header-anchor" href="#freshrss-rejects-the-login-401" aria-label="Permalink to “FreshRSS rejects the login (401)”">​</a></h2><p>You are almost certainly using the web login password. The API password is a separate value under <strong>Settings → Profile → API management</strong>. It also becomes invalid when changed, and the server caches the auth token — but it retries the login exactly once after a 401, so a rotated password recovers on the next call rather than needing a restart.</p><h2 id="freshrss-reports-the-api-as-disabled-503" tabindex="-1">&quot;FreshRSS reports the API as disabled&quot; (503) <a class="header-anchor" href="#freshrss-reports-the-api-as-disabled-503" aria-label="Permalink to “&quot;FreshRSS reports the API as disabled&quot; (503)”">​</a></h2><p><strong>Settings → Authentication →</strong> tick <strong>&quot;Allow API access&quot;</strong>. This is separate from setting an API password; both are required.</p><h2 id="the-response-is-not-json-a-404-with-a-base-url-hint" tabindex="-1">The response is not JSON / a 404 with a base-URL hint <a class="header-anchor" href="#the-response-is-not-json-a-404-with-a-base-url-hint" aria-label="Permalink to “The response is not JSON / a 404 with a base-URL hint”">​</a></h2><p><code>FRESHRSS_URL</code> is not the instance root. Give it <code>https://rss.example.com</code>, not <code>https://rss.example.com/api/greader.php</code> — the API path is appended automatically. A reverse proxy serving an interstitial or login page produces the same symptom.</p><h2 id="a-category-returns-no-articles-but-i-know-it-has-some" tabindex="-1">A category returns no articles, but I know it has some <a class="header-anchor" href="#a-category-returns-no-articles-but-i-know-it-has-some" aria-label="Permalink to “A category returns no articles, but I know it has some”">​</a></h2><p>FreshRSS matches category and label names <strong>literally, including case</strong>, and a name that does not exist returns an <em>empty list</em> rather than an error — verified against 1.29.1. So <code>category: &quot;news&quot;</code> when the category is called <code>News</code> looks exactly like &quot;nothing unread&quot;. The listing tools add a <code>hint</code> field in that situation; call <code>list_categories</code> and copy the name exactly.</p><p>The same holds for a <code>feed_id</code> that does not exist. Only a malformed built-in stream id produces HTTP 400.</p><p>Note also that categories and user labels share one namespace in this API: FreshRSS looks for a category first and falls back to a label, so a category and a label with the same name cannot be told apart.</p><h2 id="why-can-i-not-search-my-articles" tabindex="-1">Why can I not search my articles? <a class="header-anchor" href="#why-can-i-not-search-my-articles" aria-label="Permalink to “Why can I not search my articles?”">​</a></h2><p>FreshRSS offers no full-text search over the Google Reader API — the endpoints filter by stream, read state and date only. Narrow with <code>feed_id</code>, <code>category</code>, <code>since</code> and <code>until</code>, then filter the returned articles yourself. Full-text search exists in the FreshRSS web interface, but there is no API endpoint behind it.</p><h2 id="article-text-is-truncated" tabindex="-1">Article text is truncated <a class="header-anchor" href="#article-text-is-truncated" aria-label="Permalink to “Article text is truncated”">​</a></h2><p>By design. Listings return a short excerpt; pass <code>include_content: true</code> for full text, and raise <code>max_content_chars</code> (up to 20 000) if you need more. There is also a per-response budget of 60 000 characters, so a listing of 100 articles cannot bury everything else. When it runs out, the response says so and names <code>get_articles</code> as the way to fetch the rest.</p><h2 id="marking-articles-as-read-did-nothing" tabindex="-1">Marking articles as read did nothing <a class="header-anchor" href="#marking-articles-as-read-did-nothing" aria-label="Permalink to “Marking articles as read did nothing”">​</a></h2><p>Check that you passed the ids from <code>list_articles</code> or <code>list_article_ids</code> unchanged. FreshRSS reports ids as hexadecimal item tags but matches writes on the decimal row id; both forms are accepted here and converted, but a hand-edited or number-parsed id will silently address a different article — which is why ids go through <code>BigInt</code>.</p><h2 id="self-signed-certificate" tabindex="-1">Self-signed certificate <a class="header-anchor" href="#self-signed-certificate" aria-label="Permalink to “Self-signed certificate”">​</a></h2><p><code>FRESHRSS_INSECURE_TLS=true</code>. It is scoped to the connection to your instance, not process-wide, and is announced on stderr at startup. Prefer a real certificate.</p><h2 id="can-i-stop-it-from-writing-anything" tabindex="-1">Can I stop it from writing anything? <a class="header-anchor" href="#can-i-stop-it-from-writing-anything" aria-label="Permalink to “Can I stop it from writing anything?”">​</a></h2><p><code>FRESHRSS_READ_ONLY=true</code>. The eight write tools are then not registered at all, so they do not appear in <code>tools/list</code>.</p><h2 id="which-freshrss-versions-work" tabindex="-1">Which FreshRSS versions work? <a class="header-anchor" href="#which-freshrss-versions-work" aria-label="Permalink to “Which FreshRSS versions work?”">​</a></h2><p>Developed and verified against 1.29. The Google Reader endpoints it uses have been stable for years, so older releases most likely work; the <code>frss:priority</code> field and the <code>org.freshrss/main</code> and <code>org.freshrss/important</code> states are FreshRSS extensions and will simply be absent elsewhere.</p><h2 id="something-is-still-wrong" tabindex="-1">Something is still wrong <a class="header-anchor" href="#something-is-still-wrong" aria-label="Permalink to “Something is still wrong”">​</a></h2><p>Run it under the <a href="https://github.com/modelcontextprotocol/inspector" target="_blank" rel="noreferrer">MCP Inspector</a> to see raw requests and responses:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npx</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @modelcontextprotocol/inspector</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/freshrss-mcp</span></span></code></pre></div><p>Then open an <a href="https://github.com/ni-c/freshrss-mcp/issues" target="_blank" rel="noreferrer">issue</a> — with the FreshRSS version and the tool call, and <strong>without</strong> real credentials, tokens or hostnames.</p><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>FRESHRSS_READ_ONLY</code> is set, and it is a write tool.</li><li><code>FRESHRSS_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out.</li><li><code>FRESHRSS_DENY_TOOLS</code> names it, possibly through a prefix such as <code>list_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot;. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};